import{_ as o,a0 as p,w as n,s as u,ao as i,I as r,x as e,a1 as d,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何修复 apt-get update 无法添加新的 CD-ROM 的错误 | LCTT x X-CMD","titleTemplate":false,"description":"如何修复 apt-get update 无法添加新的 CD-ROM 的错误 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修复 apt-get update 无法添加新的 CD-ROM 的错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修复 apt-get update 无法添加新的 CD-ROM 的错误 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs","title":"如何修复 apt-get update 无法添加新的 CD-ROM 的错误","tag":"201505","desc":""},"relativePath":"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs.md","filePath":"[post].md"}'),m={name:"201505/20150227 How To Fix--Failed to fetch cdrom apt-get update cannot be used to add new CD-ROMs.md"};function l(c,t,f,g,b,C){const a=p("Link");return n(),u("div",null,[t[16]||(t[16]=i(`<h1 id="如何修复-apt-get-update-无法添加新的-cd-rom-的错误" tabindex="-1">如何修复 apt-get update 无法添加新的 CD-ROM 的错误 <a class="header-anchor" href="#如何修复-apt-get-update-无法添加新的-cd-rom-的错误" aria-label="Permalink to “如何修复 apt-get update 无法添加新的 CD-ROM 的错误”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/12/elementary_OS_Freya.jpg" alt=""></p><p>这些天我正在体验Elementary OS Freya，在这期间，我遇到了一个非常常见的更新错误：<strong>Failed to fetch cdrom Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</strong>。完整的错误在运行apt-get update后看上去像这样：</p><blockquote><p>W: Failed to fetch cdrom://elementary OS 0.3 <em>Freya</em> – Daily amd64 (20150208)/dists/trusty/main/binary-amd64/Packages Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</p><p>W: Failed to fetch cdrom://elementary OS 0.3 <em>Freya</em> – Daily amd64 (20150208)/dists/trusty/restricted/binary-amd64/Packages Please use apt-cdrom to make this CD-ROM recognized by APT. apt-get update cannot be used to add new CD-ROMs</p><p>E: Some index files failed to download. They have been ignored, or old ones used instead.</p></blockquote><p>本篇中，我们会了解如何修复这个错误。</p><h3 id="修复apt-get-update无法添加新的cd-rom的错误" tabindex="-1">修复apt-get update无法添加新的CD-ROM的错误 <a class="header-anchor" href="#修复apt-get-update无法添加新的cd-rom的错误" aria-label="Permalink to “修复apt-get update无法添加新的CD-ROM的错误”">​</a></h3><p>这个错误的原因是cdrom已经被包含在源之中。要修复这个问题，我们需要将它从软件源中移除。</p><p>在Ubuntu中，找到“软件与更新”：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/08/Software_Update_Ubuntu.jpeg" alt=""></p><p>在Ubuntu Software的第一个标签中，找到cdrom，如果它是勾选的，那么取消勾选。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/CDROM_Error_Update_Software_Sources.jpeg" alt=""></p><p>关闭软件源并再次运行更新。现在应该可以用了。</p><h3 id="进一步故障排除" tabindex="-1">进一步故障排除： <a class="header-anchor" href="#进一步故障排除" aria-label="Permalink to “进一步故障排除：”">​</a></h3><p>上面描述的方法已经修复了这个<strong>apt-get update cannot be used to add new CD-ROMs</strong>错误。但是这个方法对我无效，因为cdrom的选项这时是灰色的，因为我使用的live版本。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/CDROM_Update_Error.png" alt=""></p><p>现在要修复我们的问题了，我们是要采用命令行路线。打开终端并查看软件源中包含了哪些源：</p><pre><code>cat /etc/apt/sources.list
</code></pre><p>我的输出是下面这样：</p><pre><code>deb cdrom:[elementary OS 0.3 _Freya_ – Daily amd64 (20150208)]/ trusty main restricted
deb http://archive.ubuntu.com/ubuntu/ trusty main restricted universe multiverse
deb-src http://archive.ubuntu.com/ubuntu/ trusty main restricted universe multiverse
deb http://security.ubuntu.com/ubuntu/ trusty-security main restricted universe multiverse
deb-src http://security.ubuntu.com/ubuntu/ trusty-security main restricted universe multiverse
deb http://archive.ubuntu.com/ubuntu/ trusty-updates main restricted universe multiverse
deb-src http://archive.ubuntu.com/ubuntu/ trusty-updates main restricted universe multiverse
</code></pre><p>在上面的第一行中。它包含了cdrom。我们需要用‘#’来注释掉这行：</p><pre><code>#deb cdrom:[elementary OS 0.3 _Freya_ – Daily amd64 (20150208)]/ trusty main restricted
</code></pre><p>要用下面的命令来：</p><pre><code>sudo gedit /etc/apt/sources.list
</code></pre>`,23)),r("p",null,[t[1]||(t[1]=e("在你编辑完软件源后，再次运行apt-get update。“apt-get update cannot be used to add new CD-ROMs”这个错误应该已经修复了。如果你还遇到其他的问题，看一下这篇收集了大部分",-1)),d(a,{href:"http://itsfoss.com/fix-update-errors-ubuntu-1404/"},{default:s(()=>[...t[0]||(t[0]=[e("Ubuntu常见更新错误修复",-1)])]),_:1}),t[2]||(t[2]=e("的文章。",-1))]),t[17]||(t[17]=r("p",null,"我希望这篇教程对你有用。如果你还有其他的问题和建议，请在下面留言。",-1)),t[18]||(t[18]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),d(a,{href:"http://itsfoss.com/fix-failed-fetch-cdrom-aptget-update-add-cdroms/"},{default:s(()=>[...t[3]||(t[3]=[e("http://itsfoss.com/fix-failed-fetch-cdrom-aptget-update-add-cdroms/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("作者：",-1)),d(a,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...t[5]||(t[5]=[e("Abhishek",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),d(a,{href:"https://github.com/geekpi"},{default:s(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),d(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),d(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),d(a,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const T=o(m,[["render",l]]);export{D as __pageData,T as default};
